using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Collections.Generic;
[InitializeOnLoad]public static class KeyPickupRepair{
 static KeyPickupRepair(){EditorApplication.delayCall+=()=>{if(!File.Exists("Temp/key_pickup_repair.request")||EditorApplication.isPlaying)return;File.Delete("Temp/key_pickup_repair.request");var report=new List<string>();foreach(var key in Object.FindObjectsByType<StealthGame.Key>(FindObjectsSortMode.None)){var box=key.GetComponent<BoxCollider>();var renderers=key.GetComponentsInChildren<Renderer>();if(box==null||renderers.Length==0)continue;Bounds bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);if(Vector3.Distance(box.bounds.center,bounds.center)<.1f)continue;var visualPosition=renderers[0].transform.position;var old=box.bounds.center;Undo.RecordObject(box,"Align key pickup trigger with moved model");box.center=box.transform.InverseTransformPoint(bounds.center);PrefabUtility.RecordPrefabInstancePropertyModifications(box);EditorUtility.SetDirty(box);report.Add(key.name+" trigger "+old+" -> "+bounds.center+" visualPositionPreserved="+(renderers[0].transform.position==visualPosition));}var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllLines("Temp/key_pickup_repair.txt",report);};}
}
